 function qualityText(q=qualityData()){if(!q||q.pending)return '面见质量概览待同步';const t=q.summary;const items=Object.entries(Q.labels).map(([k,v])=>({label:v,count:Number(t.counts?.[k]||0)})).filter(x=>x.count>0).sort((a,b)=>b.count-a.count);return `面见质量｜截至${q.asOf}\n本月面见带来的业务反馈结构（按数量从高到低）：\n${items.map(x=>`${x.label}：${x.count}套（${M.pct(x.count,t.total)}）`).join('\n')||'暂无已归类反馈'}`;}
