 const reviewNumber=value=>Number(value||0).toLocaleString('zh-CN');
 function reviewRowName(row){return row._level==='company'?'全司':row._level==='region'?row.region:row._level==='store'?row.store:row._level==='group'?row.group:row.name;}
 function reviewLevelName(level){return {company:'全司',region:'大区',store:'门店',group:'店组',advisor:'顾问'}[level]||level;}
 function reviewCompletion(row){return row?row._target>0?M.pct(row.met,row._target):'—':'—';}
 function reviewGap(row){return row?row._target>0?Math.max(0,row._target-row.met):null:null;}
 function reviewRoot(progress,view){return progress.rows.find(row=>row._level===view.scope)||progress.rows[0];}
 function reviewChildren(progress,view){if(view.scope==='company')return {primary:progress.rows.filter(x=>x._level==='region'),secondary:progress.rows.filter(x=>x._level==='store')};if(view.scope==='region')return {primary:progress.rows.filter(x=>x._level==='store'),secondary:progress.rows.filter(x=>x._level==='group')};return {primary:progress.rows.filter(x=>x._level==='group'),secondary:[]};}
 function reviewMetricTable(title,rows,kind='progress'){
  if(!rows.length)return '';
  const full=kind==='progress',headers=full?['层级','组织','目标','面见量','完成率','差距','在售','全盘面见率','面见次数','门店TOP','户型TOP','送礼覆盖']:['层级','组织','面见量','送礼登记','送礼覆盖率'];
  const cells=row=>full?[reviewLevelName(row._level),reviewRowName(row),row._target??'—',row.met,reviewCompletion(row),reviewGap(row)??'—',row.stock,row.met_rate,row.met_count,`${row.store_top_met}/${row.store_top_stock} · ${row.store_top_rate}`,`${row.unit_top_met}/${row.unit_top_stock} · ${row.unit_top_rate}`,`${row.gift}/${row.met} · ${row.gift_rate}`]:[reviewLevelName(row._level),reviewRowName(row),row.met,row.gift,row.gift_rate];
  return `<div class="review-table-card"><h3>${E(title)}</h3><div class="review-table-scroll"><table class="review-tier-table"><thead><tr>${headers.map(x=>`<th>${E(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr class="review-row-${E(row._level)}">${cells(row).map((value,i)=>`<td class="${String(value).includes('%')?'review-percent':''} ${i===1?'review-org-name':''}">${E(value)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`;
 }
 function reviewProgressHtml(ctx){const r=ctx.root,c=reviewChildren(ctx.progress,ctx.view),target=r._target,completion=reviewCompletion(r),gap=reviewGap(r),average=r.met?`${(r.met_count/r.met).toFixed(2)}次`:'—';return `<div class="review-report"><div class="review-summary-grid">${[['月度目标',target==null?'待确认':reviewNumber(target)+'套','按当月确认目标'],['面见量',reviewNumber(r.met)+'套','按房源去重'],['目标完成率',completion,'完成进度'],['目标差距',gap==null?'—':reviewNumber(gap)+'套','距目标'],['当前在售',reviewNumber(r.stock)+'套','10月末在售'],['全盘面见率',r.met_rate,'面见量/在售'],['面见次数',reviewNumber(r.met_count)+'次','每次面见均计入'],['平均每套面见',average,'面见次数/面见量'],['门店TOP',`${r.store_top_met}/${r.store_top_stock}套`,`${r.store_top_rate} · ${r.store_top_met_count}次`],['户型TOP',`${r.unit_top_met}/${r.unit_top_stock}套`,`${r.unit_top_rate} · ${r.unit_top_met_count}次`]].map(([label,value,note])=>`<article class="review-summary-card"><span>${E(label)}</span><strong class="${String(value).includes('%')?'review-percent':''}">${E(value)}</strong><small>${E(note)}</small></article>`).join('')}</div><div class="review-callout"><strong>结果判断</strong><p>${E(target>0?`本月完成${r.met}套，目标完成率${completion}，距离目标还差${gap}套；门店TOP面见率${r.store_top_rate}，户型TOP面见率${r.unit_top_rate}。`:`本月完成${r.met}套，全盘面见率${r.met_rate}；当前范围未设置独立目标。`)}</p></div>${reviewMetricTable(ctx.view.scope==='company'?'五大区结果对比':ctx.view.scope==='region'?'区域内各门店结果':'店内各组结果',c.primary)}${reviewMetricTable(ctx.view.scope==='company'?'18家门店完整结果':'店内各组结果',c.secondary)}</div>`;}
