 function reviewRankCard(ctx,row,tone,reason){const analysisLabel=tone==='benchmark'?'突出表现':tone==='reminder'?'主要表现':'本店表现';return `<article class="review-rank-card ${tone}"><span>${E(reviewRowName(row))}</span><div class="review-rank-metrics"><p>${E(reviewMetricSentence('全盘',row.met,row.stock,row.met_rate))}</p><p>${E(reviewMetricSentence('门店TOP',row.store_top_met,row.store_top_stock,row.store_top_rate))}</p><p>${E(reviewMetricSentence('户型TOP',row.unit_top_met,row.unit_top_stock,row.unit_top_rate))}</p></div><p class="review-rank-reason"><b>${analysisLabel}：</b>${E(reason)}</p><small>${E(reviewStoreInsight(ctx,row,tone))}</small></article>`;}
